//! Terminus 6x12 bitmap font (SIL OFL, see assets/terminus-OFL.txt) for playlist text.
//! Classic skins only ship a Latin 5x6 font, which can't show most track titles.

use crate::gfx::{Framebuffer, Rect};

pub const W: i32 = 6;
pub const H: i32 = 12;

/// Records of a little-endian u32 code point then 12 row bytes, sorted by code point.
/// Generated by tools/bdf2bin.py from ter-u12n.bdf.
const GLYPHS: &[u8] = include_bytes!("../assets/terminus-6x12.bin");
const RECORD: usize = 16;

fn glyph(c: char) -> Option<&'static [u8]> {
    let count = GLYPHS.len() / RECORD;
    let code = |i: usize| {
        let r = &GLYPHS[i * RECORD..];
        u32::from_le_bytes([r[0], r[1], r[2], r[3]])
    };
    let (mut lo, mut hi) = (0, count);
    while lo < hi {
        let mid = (lo + hi) / 2;
        match code(mid).cmp(&(c as u32)) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => {
                return Some(&GLYPHS[mid * RECORD + 4..(mid + 1) * RECORD]);
            }
        }
    }
    None
}

/// Width in pixels of `s`.
pub fn width(s: &str) -> i32 {
    s.chars().count() as i32 * W
}

/// Draws `s` at (x, y) in an 0xRRGGBB colour, clipped to `clip`.
pub fn draw(fb: &mut Framebuffer, s: &str, x: i32, y: i32, rgb: u32, clip: Rect) {
    for (i, c) in s.chars().enumerate() {
        let gx = x + i as i32 * W;
        if gx >= clip.x + clip.w {
            break;
        }
        if gx + W <= clip.x {
            continue;
        }
        let Some(rows) = glyph(c).or_else(|| glyph('\u{fffd}')) else {
            continue;
        };
        for (dy, bits) in rows.iter().enumerate() {
            for dx in 0..W {
                if bits & (0x80 >> dx) != 0 {
                    fb.plot(gx + dx, y + dy as i32, rgb, clip);
                }
            }
        }
    }
}
